import{_ as e,c as o,ap as a,o as t}from"./chunks/framework.CCxIPCIe.js";const f=JSON.parse('{"title":"安装 EndeavourOS","description":"","frontmatter":{"title":"安装 EndeavourOS","date":"2026-08-20T21:30:54.795Z","length":"373字","time":"2分钟","aside":true,"hash":80718173},"headers":[],"relativePath":"note/Linux/安装EndeavourOS.md","filePath":"note/Linux/安装EndeavourOS.md"}'),n={name:"note/Linux/安装EndeavourOS.md"};function r(l,s,p,c,i,d){return t(),o("div",null,s[0]||(s[0]=[a(`<p>很快就要毕业了，因此我不得不换回老电脑联想小新锐 7000。这台老电脑的配置还是 18 年的，内存是 DDR3 8G，CPU 是 i7-7700，显卡是 GTX1050Ti，128G 的固态+1T 的机械硬盘。这台电脑之前装的是 Deepin V20，感觉还是比较卡顿，所以我决定这次直接一步到位加入 Arch 神教。不过据说原生 Arch 安装起来特别麻烦，所以还是选择了 EndeavourOS 这个 Arch 的衍生发行版。</p><p>在官网上下载了最新的 ISO 镜像以后，用 <code>dd</code> 命令写入 U 盘。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">sudo</span><span style="color:#2AA198;"> dd</span><span style="color:#2AA198;"> if=&quot;path_to_iso&quot;</span><span style="color:#2AA198;"> of=&quot;path_to_usb&quot;</span><span style="color:#2AA198;"> bs=4M</span><span style="color:#2AA198;"> status=progress</span><span style="color:#2AA198;"> oflag=sync</span></span></code></pre></div><p>在 BIOS 中设置 U 盘启动后，（注意要关闭 secure boot），进入 EndeavourOS 的 live 系统，选择安装。头一遍安装选择了自动分区，使用了自带快照的 btrfs 文件系统作为根文件系统，但是它没有区分出 <code>/boot</code> 分区，结果导致安装后无法启动。 GRUB 启动器报错 <code>premature end of file /@/boot/vmlinuz-linux</code>。上网搜索发现原因是由于 /boot 存储在 btrfs 子卷中（可能启用了 CoW 功能），而 GRUB 尚不完全支持该功能，因此 GRUB 无法读取内核/initramfs。<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> 于是重新进入 live 系统，选择手动分区，分区如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>/boot/efi – 512 MiB, FAT32, ESP</span></span>
<span class="line"><span>/boot – 1 GiB, ext4 (outside of btrfs, no subvolume)</span></span>
<span class="line"><span>/ – rest of disk, btrfs with standard subvolumes (e.g., @, @home, etc.)</span></span></code></pre></div><p>安装完毕后，成功进入系统。</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://codeberg.org/Calamares/calamares/issues/2440#issuecomment-5455743" target="_blank" rel="noreferrer">https://codeberg.org/Calamares/calamares/issues/2440#issuecomment-5455743</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>`,8)]))}const _=e(n,[["render",r]]);export{f as __pageData,_ as default};
